"""Shared helpers for HTML report modules.

Report modules may not import each other, so the common pieces — channel
resolution, safe paths, link formatting, escaping and in-flight deduplication —
live here as a shared service.
"""

from __future__ import annotations

import asyncio
import html
import re
from pathlib import Path
from typing import Any
from urllib.parse import quote

from bot.core.event_router import CommandContext

SAFE_LOGIN = re.compile(r"[A-Za-z0-9_]{1,32}")

FOOTER = (
    '<footer>Generated by <a href="https://hy.tencent.ai/research/hy4-flash" '
    'alt="Tencent Hy4 Flash"> Tencent Hy4 Flash </a> with &#10084; from '
    '<a href="https://www.tiktok.com/@unkowncitizen93628/video/7485118733644582175"> '
    "&#x1f1e8;&#x1f1f3; </a> </footer>"
)


def escape(value: object) -> str:
    """Escape a dynamic value before it is placed into HTML."""
    return html.escape(str(value), quote=True)


def report_shell(title: str, subtitle: str, style: str, body: str) -> str:
    """Wrap a report body in the shared HTML document, title and footer."""
    return (
        '<!DOCTYPE html>\n<html lang="en">\n<head>\n'
        '<meta charset="UTF-8">\n'
        '<meta name="viewport" content="width=device-width, initial-scale=1.0">\n'
        f"<title>{escape(title)}</title>\n"
        f"<style>{style}</style>\n"
        "</head>\n<body>\n\n"
        f"<h1>{escape(title)}</h1>\n"
        f'<p class="subtitle">{escape(subtitle)}</p>\n\n'
        f"{body}\n{FOOTER}\n\n</body>\n</html>\n"
    )


def channel_login(settings: Any, channel_id: str) -> str | None:
    """Return the configured, URL-safe login for a channel ID."""
    twitch = settings.twitch
    for known_id, login in zip(twitch.channel_id, twitch.channel, strict=False):
        if known_id == channel_id and SAFE_LOGIN.fullmatch(login):
            return login
    return None


def is_report_admin(permissions: Any, ctx: CommandContext) -> bool:
    """Only bot admins and the channel owner may generate reports."""
    return permissions is not None and permissions.can_manage_channel(ctx)


def emote_image_url(emote_data: dict) -> str:
    """Return a validated https image URL for a 7TV emote, or an empty string."""
    host = emote_data.get("host")
    if not isinstance(host, dict):
        data = emote_data.get("data", {})
        host = data.get("host", {}) if isinstance(data, dict) else {}
    if not isinstance(host, dict):
        return ""

    url_base = str(host.get("url", "") or "")
    if url_base.startswith("//"):
        url_base = "https:" + url_base
    if not url_base.startswith("https://"):
        return ""

    files = host.get("files") or []
    name = ""
    for entry in files:
        if isinstance(entry, dict) and entry.get("name") == "2x.webp":
            name = "2x.webp"
            break
    if not name and files and isinstance(files[0], dict):
        name = str(files[0].get("name", "") or "")
    if not name and emote_data.get("id"):
        name = "2x.webp"
    if not name:
        return ""
    return f"{url_base.rstrip('/')}/{quote(name, safe='._-')}"


def emote_link(emote_data: dict) -> str:
    """Return a 7TV link with a safely encoded emote ID."""
    return f"https://7tv.app/emotes/{quote(str(emote_data.get('id', '')), safe='')}"


def report_link(url_prefix: str, login: str, filename: str) -> str:
    """Build the public chat link for a report."""
    return f"{url_prefix.rstrip('/')}/{login}/{filename}"


def write_report(reports_dir: str, login: str, filename: str, html_text: str) -> Path:
    """Atomically write ``reports_dir/login/filename`` and return its path."""
    directory = Path(reports_dir) / login
    directory.mkdir(parents=True, exist_ok=True)
    target = directory / filename
    temporary = target.with_name(target.name + ".tmp")
    temporary.write_text(html_text, encoding="utf-8")
    temporary.replace(target)
    return target


class ReportCoordinator:
    """Prevent duplicate reports of the same kind in one channel."""

    def __init__(self) -> None:
        self._lock = asyncio.Lock()
        self._inflight: set[str] = set()

    async def claim(self, key: str) -> bool:
        async with self._lock:
            if key in self._inflight:
                return False
            self._inflight.add(key)
            return True

    async def release(self, key: str) -> None:
        async with self._lock:
            self._inflight.discard(key)
